-- الجولة الختامية لتدقيق consultant_scenarios
-- ===========================================================================
-- تكملة sql/2026-07-30_consultant_audit_full.sql (الذي شغّلته سابقاً):
--   • الملاحظات المتوسطة/المنخفضة التي اكتمل تفنيدها الآن — كل تصحيح صمد
--     أمام مفنِّد مستقل واحد على الأقل قرأ النص الرسمي بنفسه.
--   • صف syrian-prohibited-check: كان يستشهد بنظام الإغلاق (عتبة 20%) كأنه
--     على حاله، بينما قرارات حزيران 2026 أعادت فتح نحو 80% من الأحياء —
--     النص الجديد يقول الحقيقتين معاً: العتبة سارية كأساس، ومعظم القائمة
--     شُطبت، والفيصل مديرية الهجرة في ولايتك. وإحالته الداخلية كانت مكسورة
--     (syrians-prohibited-areas غير موجود) فصارت إلى address-registration-closed.
-- ما رفضه التفنيد أو احتاج قراراً بشرياً لم يدخل هذا الملف.
-- steps و docs من نوع jsonb. شغّله في Supabase → SQL Editor.

UPDATE consultant_scenarios SET
    description = 'القيادة برخصة أجنبية في تركيا مسموحة لمدة 6 أشهر للأجانب (وسنتان للمواطنين الأتراك الحاملين رخصة صادرة من الخارج)، وفق مديرية النفوس والجنسية NVİ. بعد انقضاء الستة أشهر يجب استبدال الرخصة الأجنبية برخصة تركية (tebdil)؛ والقيادة بعدها تُعدّ قيادة بلا رخصة سارية وتُعرّضك لغرامة وحجز المركبة. ابدأ إجراءات الاستبدال قبل انتهاء المدة بوقت كافٍ. لا تخاطر لأن “القيادة بدون رخصة” لها غرامات كبيرة. القيادة برخصة أجنبية في تركيا مسموحة للأجانب لمدة 6 أشهر تُحسب من تاريخ دخولك تركيا (وسنتان للمواطنين الأتراك الحاملين رخصة صادرة من الخارج)، وفق مديرية النفوس والجنسية NVİ ولائحة المرور. بعد انقضاء المدة يجب استبدال الرخصة الأجنبية برخصة تركية (tebdil)؛ والقيادة بعدها تُعدّ قيادة بلا رخصة سارية وتُعرّضك لغرامة ولمنع المركبة من السير. ابدأ إجراءات الاستبدال قبل انتهاء المدة بوقت كافٍ.',
    last_update = '2026-07'
WHERE id = 'car-drive-with-foreign-license';

UPDATE consultant_scenarios SET
    steps = '["حدد النشاط (NACE) بدقة واختر عنواناً صالحاً للتسجيل (مكتب/عنوان شركة مقبول).", "ابدأ عبر MERSIS لتجهيز بيانات الشركة والمسودة الأساسية (عقد تأسيس/نظام).", "اعتمد المحاسب (Mali Müşavir) لأنه سيقود جزءاً كبيراً من التسجيلات والضرائب.", "وقّع عقد التأسيس أمام الموظف المخوَّل في مديرية السجل التجاري نفسها (المادة 575 من قانون التجارة 6102) — لم يعد يُشترط النوتر لذلك. وتواقيع المخوَّلين بالتوقيع تُسحب إلكترونياً من قواعد بيانات الدولة، وعند عدم وجودها يُقدَّم بيان التوقيع لمديرية السجل التجاري (المادة 40/2). يبقى النوتر لازماً فقط للوكالات والترجمات.", "افتح ملف ضريبي في مصلحة الضرائب وفعّل الدفاتر/اللوحات/الفواتير الإلكترونية حسب النشاط.", "افتح حساباً بنكياً للشركة، وجهّز قنوات الدفع الرسمية.", "فعّل SGK للموظفين إن وُجدوا — ولاحظ أن تأمينك أنت (Bağ-Kur 4/b) كشريك في شركة محدودة يبدأ إلزامياً من تاريخ قيد الشركة في السجل التجاري حتى لو لم يكن لديك أي موظف (المادة 7/ب من قانون 5510)، بحد أدنى ≈ 11,808 ليرة شهرياً في 2026."]'::jsonb,
    last_update = '2026-07'
WHERE id = 'company-setup';

UPDATE consultant_scenarios SET
    steps = '["إذا قررت التداول: منذ 2/7/2024 (القانون 7518) صارت منصات الأصول الرقمية العاملة في تركيا خاضعة لترخيص ورقابة هيئة أسواق المال SPK. قبل أن تودع أي مبلغ، تحقّق من اسم المنصة في القوائم الرسمية المنشورة على موقع الهيئة (spk.gov.tr → «kripto varlık hizmet sağlayıcılar»): قائمة العاملين، قائمة من أعلن التصفية، وقائمة من هم قيد التصفية. المنصة غير المدرجة تعمل خارج الإطار القانوني وأموالك فيها بلا حماية.", "لا تخلط بين «تداول» و«دفع»: التداول عبر منصة مرخّصة من هيئة أسواق المال SPK ممكن، أما الدفع بالعملات الرقمية فمحظور بنص المادة 3 من لائحة 16/4/2021؛ كما تمنع المادة 4 مؤسسات الدفع والنقود الإلكترونية من الوساطة في تحويل الأموال إلى منصات الأصول الرقمية.", "احتفظ بسجل عملياتك (إيداع/سحب/صفقات) لأن البنوك قد تسأل عن مصدر الأموال.", "لا تحول مبالغ كبيرة دفعة واحدة لحسابك البنكي بدون تفسير واضح.", "اعتبر التقلبات عالية؛ لا تستخدم أموال الإيجار/المعيشة كاستثمار عالي المخاطر."]'::jsonb,
    last_update = '2026-07'
WHERE id = 'daily-crypto';

UPDATE consultant_scenarios SET
    description = 'يحق لك تغيير طبيب العائلة، لكن لا يجوز التغيير قبل مرور ثلاثة أشهر إلا في الحالات الاضطرارية — وهذه قاعدة وطنية موحّدة (المادة 8 من لائحة تطبيق طب العائلة) وليست لائحة ولائية. العملية بسيطة وتتم إلكترونياً أو شخصياً. العملية بسيطة وتتم إلكترونياً أو شخصياً.',
    legal = 'القيد وطني وليس ولائياً: تنص المادة 8 من لائحة تطبيق طب العائلة على أنه «لا يجوز تغيير طبيب العائلة قبل ثلاثة أشهر إلا في الحالات الاضطرارية»، أي تغيير واحد كحدّ أقصى كل ثلاثة أشهر في عموم تركيا. أما المادة 5 من القانون 5258 فتجعل تحديد هذه المدة من صلاحية وزارة الصحة.',
    steps = '["ادخل على E-Devlet → Aile Hekimi Sorgulama لمعرفة طبيبك الحالي.", "للتغيير إلكترونياً: e-Devlet ← «Aile Hekimi Değiştirme» (turkiye.gov.tr/saglik-aile-hekimi-degistirme) — الخدمة متاحة في عموم تركيا، ويمكن أيضاً إجراء التغيير عبر e-Nabız أو بطلب خطي لدى الطبيب الجديد أو مركز الصحة المجتمعية.", "للتغيير شخصياً: اذهب إلى ASM الجديد الذي تريد التسجيل فيه واطلب النقل.", "سيُنقل ملفك الصحي تلقائياً للطبيب الجديد."]'::jsonb,
    last_update = '2026-07'
WHERE id = 'daily-family-doctor-change';

UPDATE consultant_scenarios SET
    description = 'FAST هو نظام تحويل فوري بين البنوك 24/7. مفيد لدفع إيجار/مستحقات بسرعة، لكن له سقف لكل عملية يحدّده البنك المركزي التركي (TCMB) لكل البنوك معاً، وليس سقفاً يومياً يختلف من بنك لآخر: منذ 4 نيسان/أبريل 2024 السقف 100,000 ليرة للتحويلات النقدية و250,000 ليرة لمدفوعات المتاجر عبر رمز FAST-TR بالتحقق الديناميكي. (قد يضيف بنكك قيوداً إضافية داخل تطبيقه، لكن لا يستطيع تجاوز سقف المركزي.)',
    steps = '["تحقق من تطبيق بنكك: هل يدعم FAST؟ وتذكّر أن السقف الأساسي لكل عملية يحدّده البنك المركزي لكل البنوك (100,000 ليرة للتحويلات منذ 4/4/2024)، وقد يضيف بنكك قيوداً داخلية أضيق.", "استخدم FAST للتحويلات الصغيرة والمتوسطة عندما تحتاج وصولاً فورياً.", "إذا كان المبلغ أكبر من سقف FAST: أرسله دفعة واحدة عبر EFT/حوالة مع بيان سبب التحويل ومستنداته. لا تلجأ إلى تقسيم المبلغ إلى دفعات صغيرة للتحايل على السقف: لوائح مكافحة غسل الأموال تحتسب «العمليات المتعددة المرتبطة ببعضها» كعملية واحدة، فالتقسيم لا يتجاوز الرقابة بل يلفت الانتباه وقد يؤدي إلى بلاغ عملية مشبوهة وتجميد الحساب.", "احتفظ بإيصال التحويل دائماً خصوصاً للإيجار أو معاملات مهمة.", "إذا فشل التحويل: تحقق من الحد اليومي أو من ساعات الصيانة لدى البنك."]'::jsonb,
    last_update = '2026-07'
WHERE id = 'daily-fast';

UPDATE consultant_scenarios SET
    steps = '["نظام e-İkamet (e-ikamet.goc.gov.tr): استخدمه فقط لـ تقديم طلب إقامة جديد أو تجديد إقامة. يُنشئ ملفاً كاملاً مع موعد.", "نظام المواعيد (randevu.goc.gov.tr، ويُتاح الدخول إليه عبر e-Devlet): استخدمه لحجز موعد في مديرية الهجرة لتحديث بيانات، أو تسليم مستندات ناقصة، أو مراجعة بخصوص تبليغ. أما الرقم 157 (YİMER) فهو خط استعلام وبلاغ ولا يُحجَز عبره موعد؛ استخدمه للسؤال عن المستندات المطلوبة وإجراءات معاملتك.", "لحجز موعد e-İkamet: أدخل بياناتك → اختر الولاية → حدد نوع الطلب → اختر أقرب موعد متاح → ستحصل على رقم طلب ورمز التحقق.", "لحجز موعد عام: ادخل إلى randevu.goc.gov.tr (بحساب e-Devlet أو بتسجيل داخل النظام) وحدّد الولاية ونوع المعاملة. الاتصال بالرقم 157 يفيد للاستعلام عن المستندات المطلوبة وعن حالة معاملتك، لا لحجز الموعد.", "اذهب في الموعد قبل 15 دقيقة مع كافة المستندات مرتبة.", "ملاحظة: المواعيد في إسطنبول وأنقرة وإزمير قد تتأخر لأسابيع — احجز مبكراً."]'::jsonb,
    last_update = '2026-07'
WHERE id = 'daily-goc-appointment';

UPDATE consultant_scenarios SET
    steps = '["قدّم شكوى أولاً لخدمة العملاء (مكتوبة عبر التطبيق أو الموقع)", "الأصل أن تحلّ الشركة شكواك خلال عشرة أيام عمل كحدّ أقصى من تاريخ تقديمها عبر نظام شكاوى الشركة (المادة 6 من «أسس وإجراءات حل شكاوى المستهلك من قِبَل المشغّلين» الصادرة عن BTK). إذا لم تُحلّ خلال هذه المدة، قدّم شكوى إلى BTK.", "الشكوى في BTK عبر: btk.gov.tr أو تطبيق BTK", "يمكنك أيضاً الشكوى عبر CİMER", "لإلغاء اشتراك ضمن التزام (Taahhüt): بدل الإلغاء محدَّد بسقف قانوني ولا يساوي «باقي قيمة العقد». وفق المادة 12/5 من لائحة حقوق المستهلك في قطاع الاتصالات، لا يجوز أن يتجاوز المبلغ المطلوب منك مجموع ما لم يُحصَّل من قيمة الخصومات والجهاز والمزايا التي حصلت عليها؛ وإن كان مجموع الأقساط غير المستحقة حتى نهاية مدة الالتزام أقل من ذلك، فالمبلغ الأقل هو المعتمد. اطلب من الشركة كتابياً بيان طريقة احتساب المبلغ، واعترض عبر نظام شكاوى الشركة ثم BTK إن تجاوزت السقف."]'::jsonb,
    tip = 'قبل توقيع عقد جديد، اسأل عن مدة الالتزام (Taahhüt) وعن طريقة احتساب بدل الإلغاء. واعلم حقاً مهماً: في اشتراكات الإنترنت/الهاتف الثابت (غير الخطوط الخلوية)، إذا انتقلت إلى سكن جديد وتعذّر فعلياً تقديم الخدمة نفسها في العنوان الجديد، يحقّ لك فسخ الاشتراك دون دفع أي بدل إلغاء شرط إثبات تغيير محل السكن (المادة 12/6 من لائحة حقوق المستهلك في قطاع الاتصالات).',
    last_update = '2026-07'
WHERE id = 'daily-internet-telecom';

UPDATE consultant_scenarios SET
    legal = 'قنوات بلاغ رسمية ضمن منظومة الأمن/الطوارئ. مهم: خدمات الحماية ودور الإيواء (kadın konukevi) تُقدَّم للنساء الأجنبيات «دون تمييز بسبب الوضع القانوني أو الجنسية» بحسب وزارة الأسرة والخدمات الاجتماعية — أي أن انتهاء الإقامة أو الكملك لا يمنعك من طلب الحماية. إضافة إلى 112 وتطبيق KADES، يمكن الاتصال بخط الدعم الاجتماعي 183 الذي ينقل الحالة فوراً إلى الشرطة أو الجندرما. مهم: خدمات الحماية ودور الإيواء (kadın konukevi) تُقدَّم للنساء الأجنبيات «دون تمييز بسبب الوضع القانوني أو الجنسية» بحسب وزارة الأسرة والخدمات الاجتماعية — أي أن انتهاء الإقامة أو الكملك لا يمنعك من طلب الحماية. إضافة إلى 112 وتطبيق KADES، يمكن الاتصال بخط الدعم الاجتماعي 183 الذي ينقل الحالة فوراً إلى الشرطة أو الجندرما.',
    last_update = '2026-07'
WHERE id = 'daily-kades';

UPDATE consultant_scenarios SET
    cost = 'رسمان إلزاميان حتى في حالة الفقدان أو السرقة: بدل الورقة ذات القيمة (değerli kâğıt bedeli) وحصة الوقف (vakıf payı). المبلغان يُحدَّثان سنوياً — تحقّق من المبلغ الساري لدى مديرية النفوس أو موقعها قبل الموعد. أما إيصال الرخصة عبر PTT فلا يُدفع مقابله شيء.',
    steps = '["حجز موعد نفوس لخدمة السائقين (Sürücü Belgesi).", "[رابط حجز موعد النفوس - رخصة القيادة](https://randevu.nvi.gov.tr/#/nvi/randevu-al)", "تجهيز صورة بيومترية + تقرير صحي.", "دفع الرسوم إلزامي: بدل الورقة ذات القيمة (değerli kâğıt bedeli) وحصة الوقف (vakıf payı) واجبة الدفع حتى في حالة الفقدان أو السرقة — سدّدها قبل موعدك.", "الحضور للموعد واستكمال الإجراء.", "استلام الرخصة بالبريد."]'::jsonb,
    last_update = '2026-07'
WHERE id = 'daily-lost-driving-license';

UPDATE consultant_scenarios SET
    cost = 'حصة المشاركة في الكشف (Katılım payı) للمؤمَّنين لدى SGK بحسب أرقام المؤسسة لعام 2026: صفر في مؤسسات الرعاية الأولية (مركز صحة العائلة)، و26 ليرة في مؤسسات الدرجة الثانية والثالثة الحكومية، و60 ليرة في مؤسسات الدرجة الثانية والثالثة الخاصة. بدون تأمين: يُحاسَب الأجنبي الحاصل على إقامة والذي لا يستفيد من التأمين الصحي العام (GSS) وفق تعرفة «السياحة الصحية وصحة السائح»، وهي تعرفة منشورة من وزارة الصحة (ملحق EK-2) وتُعدّ أسعارها حدّاً أدنى. اسأل قسم المحاسبة في المشفى عن سعر الكشف وفق هذه التعرفة قبل المراجعة — ولا تعتمد على مبلغ تقديري. التحاليل والأشعة: مجانية مع SGK، مدفوعة بدونه.',
    description = 'MHRS (Merkezi Hekim Randevu Sistemi) هو نظام حجز المواعيد المركزي للمشافي الحكومية. MHRS (Merkezi Hekim Randevu Sistemi) هو نظام حجز المواعيد المركزي للمشافي الحكومية. الحجز يتم برقم الهوية (TC أو الرقم الأجنبي) مع حساب e-Devlet، أو عبر ALO 182. التأمين الصحي ليس شرطاً معلَناً للحجز في المصادر الرسمية — هو يحدّد من يدفع تكلفة العلاج: مع SGK/GSS تدفع حصة المشاركة فقط، وبدون تغطية تُحاسَب وفق تعرفة وزارة الصحة.',
    steps = '["تأكد من وجود تأمين صحي ساري: SGK عبر العمل، أو تأمين خاص مقبول، أو GSS (التأمين الصحي العام).", "حمّل تطبيق MHRS أو ادخل على mhrs.gov.tr أو اتصل على ALO 182.", "سجّل الدخول برقم TC + كلمة مرور E-Devlet.", "اختر: التخصص → المدينة → المشفى → الطبيب → الموعد المتاح.", "ستحصل على رسالة تأكيد SMS. اذهب في الموعد قبل 15 دقيقة.", "ملاحظة: حجز موعد في MHRS مرتبط برقم الهوية (التركي أو رقم الأجانب الذي يبدأ بـ99)، ولا يوجد أي نص رسمي يقول إن النظام يحجب كل المواعيد عمّن لا يملك تأميناً. عدم امتلاك تأمين لا يعني أن المشافي الحكومية مغلقة أمامك: بحسب «أسس وإجراءات تعرفة الأسعار» لوزارة الصحة يُعالَج المقيم غير المستفيد من التأمين الصحي العام في المؤسسات الحكومية بصفة مريض بأجر وفق تعرفة الوزارة. إن لم يظهر لك موعد في التطبيق فراجع المشفى الحكومي مباشرة واسأل عن إجراءات المرضى غير المؤمَّنين."]'::jsonb,
    tip = 'مواعيد التخصصات المطلوبة (عيون، جلدية) تنفد بسرعة. حاول الحجز في الصباح الباكر مواعيد التخصصات المطلوبة (عيون، جلدية) تنفد بسرعة. تابع التطبيق في أوقات مختلفة من اليوم لاقتناص المواعيد الجديدة أو الملغاة — لا يوجد إعلان رسمي عن ساعة محددة تُفتح فيها المواعيد..',
    last_update = '2026-07'
WHERE id = 'daily-mhrs-booking';

UPDATE consultant_scenarios SET
    steps = '["حدد هل تحتاج: (1) ترجمة محلفة + تصديق نوتر، أم (2) تصديق توقيع/تعهد.", "إذا كانت ترجمة: اختر ترجماناً محلفاً ثم خذ الترجمة للنوتر للتصديق.", "اذهب للنوتر مع الهوية والأصل والنسخ. وإن كنت لا تتقن التركية، فالمادة 74 من قانون النوتر توجب حضور مترجم محلّف معك أثناء المعاملة (وكالة، تعهد، تصديق توقيع) وإلا لن تُنجَز؛ اسأل النوتر مسبقاً عن المترجمين المعتمدين لديه وعن أجرهم. وإن كنت لا تتقن التركية، فالمادة 74 من قانون النوتر توجب حضور مترجم محلّف معك أثناء المعاملة (وكالة، تعهد، تصديق توقيع) وإلا لن تُنجَز؛ اسأل النوتر مسبقاً عن المترجمين المعتمدين لديه وعن أجرهم.", "ادفع الرسوم واستلم النسخة المصدّقة."]'::jsonb,
    last_update = '2026-07'
WHERE id = 'daily-notary';

UPDATE consultant_scenarios SET
    description = 'إجراءات عاجلة إذا رُفض دخولك إلى تركيا في المطار أو المعبر الحدودي. وإن كنت خائفاً على حياتك أو حريتك في البلد الذي ستُعاد إليه فقُلها صراحةً للموظف واطلب تقديم طلب حماية دولية: المادة 8 من القانون 6458 تمنع تفسير شروط الدخول أو تطبيقها بما يعرقل تقديم طلب الحماية الدولية، والمادة 4 تمنع إعادتك إلى مكان تكون فيه حياتك أو حريتك مهدَّدة. وإن كنت خائفاً على حياتك أو حريتك في البلد الذي ستُعاد إليه فقُلها صراحةً للموظف واطلب تقديم طلب حماية دولية: المادة 8 من القانون 6458 تمنع تفسير شروط الدخول أو تطبيقها بما يعرقل تقديم طلب الحماية الدولية، والمادة 4 تمنع إعادتك إلى مكان تكون فيه حياتك أو حريتك مهدَّدة.',
    legal = 'قانون الأجانب والحماية الدولية رقم 6458 — المادة 7 (الأجانب الذين لا يُسمح بدخولهم و"الراكب غير المقبول")، والمادة 7/2 (وجوب تبليغك بالقرار وبكيفية استعمال حقك في الاعتراض)، والمادة 6/5 (لا يجوز إبقاؤك للتدقيق الموسّع أكثر من أربع ساعات)، والمادة 9 (حظر الدخول ومدته ورفعه)',
    last_update = '2026-07'
WHERE id = 'emergency-airport-denied';

UPDATE consultant_scenarios SET
    docs = '["صورة عن الهوية/الكملك", "تقرير طبي (إن وجد)", "أي دليل على العنف (صور/رسائل) — إن وُجد فقط. المادة 8/3 من القانون 6284 تنص صراحة على أنه لا يُطلب أي دليل أو وثيقة لإصدار أمر الحماية، فلا تؤجّل الطلب لأنك لا تملك تقريراً طبياً أو صوراً. — إن وُجد فقط. المادة 8/3 من القانون 6284 تنص صراحة على أنه لا يُطلب أي دليل أو وثيقة لإصدار أمر الحماية، فلا تؤجّل الطلب لأنك لا تملك تقريراً طبياً أو صوراً."]'::jsonb,
    tip = 'أمر الحماية يصدر حتى لو لم يكن لديك إقامة رسمية. وإذا رُفض طلبك فلديك أسبوعان فقط من تاريخ التبليغ للاعتراض أمام محكمة الأسرة (المادة 9 من القانون 6284) — وقرار الرفض يُبلَّغ لك أنت وحدك، فسجّل تاريخ التبليغ فور استلامه. جهة الاعتراض تفصل خلال أسبوع وقرارها نهائي.',
    last_update = '2026-07'
WHERE id = 'emergency-domestic-violence';

UPDATE consultant_scenarios SET
    cost = 'الولادة الحكومية: مجانية مع GSS | بدون تأمين: لا يوجد رقم ثابت — تُحسب التكلفة وفق التعرفة الرسمية لوزارة الصحة وتعليمات التطبيق الصحي (SUT) وتتغير سنوياً وبحسب نوع الولادة، فاسألي محاسبة المشفى مسبقاً. والمشمولون بالحماية المؤقتة تُغطّى ولادتهم وفق المادة 27 من لائحة الحماية المؤقتة (مع «مساهمة» وفق SUT منذ 28/11/2025 تُستردّ عبر صناديق التضامن الاجتماعي لمن يثبت عجزه عن الدفع).',
    steps = '["سجّلي الحمل عند طبيب العائلة أو في مشفى حكومي", "متابعة الحمل مجانية في مراكز صحة الأسرة (ASM) ومراكز صحة المهاجرين لمن لديه تسجيل (حماية مؤقتة أو إقامة برقم كيملك) — ابدئي المتابعة من هناك. أما في المشافي الحكومية فقد تُحتسب رسوم لغير المؤمَّنات وفق التعرفة الرسمية، وفي الحالة الطارئة (كالولادة) يُستقبل الجميع دون النظر إلى التأمين أو القدرة على الدفع.", "اختاري مشفى الولادة مسبقاً واحجزي عبر MHRS", "بعد الولادة: سجّلي المولود في المشفى ثم في النفوس خلال 30 يوماً (المادة 15 من القانون 5490). وإن كنتِ مشمولة بالحماية المؤقتة فالمهلة الملزِمة لكِ أقصر: عليك تبليغ إدارة الهجرة بالولادة خلال 20 يوم عمل (المادة 33/2-د من لائحة الحماية المؤقتة). (المادة 15 من القانون 5490). وإن كنتِ مشمولة بالحماية المؤقتة فالمهلة الملزِمة لكِ أقصر: عليك تبليغ إدارة الهجرة بالولادة خلال 20 يوم عمل (المادة 33/2-د من لائحة الحماية المؤقتة).", "إعانة الولادة (Doğum Yardımı) مخصّصة للمواطنين الأتراك فقط: تشترط وزارة الأسرة والخدمات الاجتماعية أن يكون أحد الوالدين مواطناً تركياً، وأن يكون مقدّم الطلب وصاحب الحق والطفل نفسه مواطنين أتراكاً — فلا تنطبق على الأجانب ولا على حملة البطاقة الزرقاء. إن كنت أجنبية فاسألي مديرية الأسرة والخدمات الاجتماعية في ولايتك عن المساعدات الاجتماعية المتاحة لك بدلاً منها."]'::jsonb,
    last_update = '2026-07'
WHERE id = 'family-pregnancy-birth';

UPDATE consultant_scenarios SET
    cost = 'التكاليف تتغيّر كل يناير (رُفعت الرسوم المقطوعة 18.95% في 1/1/2026 وصدرت تعرفة النوتر الجديدة في 30/12/2025). للعلم بحدودها في 2026: رسم المراجعة لبدء إجراء İcra وحده 732 ليرة، ورسم المراجعة في محكمة الصلح 335.20 ليرة يُضاف إليه رسم قرار نسبي (68.31 بالألف من المبلغ، يُدفع ربعه مقدماً) وسلفة مصاريف تُقدّرها المحكمة. اسأل النوتر أو قلم المحكمة عن الرسم الفعلي قبل التقديم.',
    steps = '["تأكد من أن مبلغ التأمين المدفوع لا يتجاوز 3 أشهر إيجار (الحد القانوني الأقصى — المادة 342 من TBK).", "عند انتهاء العقد: سلّم المنزل نظيفاً مع إصلاح أي أضرار تسببت بها (الاستهلاك الطبيعي ليس ضرراً).", "وثّق حالة المنزل عند التسليم: صوِّر كل غرفة بالفيديو + وقّع محضر تسليم مع المالك. وتذكّر المادة 335 من TBK: المالك ملزم بمعاينة المنزل وقت الاستلام وإبلاغك كتابياً وفوراً بأي نقص أو عيب يحمّلك مسؤوليته، وإن لم يفعل تتحرر من المسؤولية عن كل ما كان يمكن كشفه بالمعاينة العادية. الاستثناء الوحيد: العيوب الخفية التي لا تظهر بالفحص المعتاد تبقى مسؤوليتك، وعلى المالك إبلاغك كتابياً فور اكتشافها. لذلك لا تقبل خصومات متأخرة عن عيوب كانت ظاهرة يوم التسليم. وتذكّر المادة 335 من TBK: المالك ملزم بمعاينة المنزل وقت الاستلام وإبلاغك كتابياً وفوراً بأي نقص أو عيب يحمّلك مسؤوليته، وإن لم يفعل تتحرر من المسؤولية عن كل ما كان يمكن كشفه بالمعاينة العادية. الاستثناء الوحيد: العيوب الخفية التي لا تظهر بالفحص المعتاد تبقى مسؤوليتك، وعلى المالك إبلاغك كتابياً فور اكتشافها. لذلك لا", "اطلب التأمين كتابياً: أرسل إنذاراً عبر نوتير (İhtarname) إذا رفض المالك الإعادة.", "إذا لم يستجب: يمكنك بدء إجراء تنفيذ (İcra takibi) أو رفع دعوى في Sulh Hukuk Mahkemesi. انتبه: في إجراء التنفيذ يكفي أن يعترض المالك خلال مهلته ليتوقف الإجراء (المادة 66 من İİK)، وعندها عليك رفع دعوى «itirazın iptali» خلال سنة من تبليغك الاعتراض (المادة 67). ولا يُحكم عليك بتعويض (لا يقل عن 20%) إلا إذا طلبه الطرف الآخر وثبت أنك بدأت التنفيذ بغير حق وبسوء نية — فلا تخف من المسار إن كانت مطالبتك موث", "ملاحظة مهمة: إذا كان التأمين مودعاً في حساب بنكي وفق المادة 342 من TBK، فالبنك ملزم بإعادته لك بمجرد طلبك إذا لم يُبلغه المالك كتابياً — خلال ثلاثة أشهر من انتهاء العقد — بأنه رفع دعوى أو بدأ إجراء تنفيذ/إفلاس ضدك. قبل ذلك لا يُعيده البنك إلا برضا الطرفين أو بتنفيذ مكتسب القطعية أو بحكم محكمة نهائي."]'::jsonb,
    last_update = '2026-07'
WHERE id = 'housing-deposit';

UPDATE consultant_scenarios SET
    tip = 'احتفظ بنسخة من العقد ودفعات الإيجار. لا تدفع الزيادة غير القانونية ثم تشتكي — ارفض من البداية كتابياً. الفرق المدفوع فوق السقف قد يكون قابلاً للاسترداد قضائياً، لكن مدة التقادم محل خلاف قانوني (قد تكون سنتين فقط من علمك بالدفع الزائد بحسب تكييف المحكمة) — لا تؤجل المطالبة اعتماداً على مهلة طويلة، واستشر محامياً بسرعة.',
    last_update = '2026-07'
WHERE id = 'housing-rent-increase';

UPDATE consultant_scenarios SET
    cost = 'رسم الطابو وفق قانون الرسوم 492 (التعرفة 4، البند 20/أ): 2% على البائع و2% على المشتري من الثمن المصرَّح به (وعملياً كثيراً ما يتحمّل المشتري النسبتين معاً 4% بالاتفاق) + تقرير التقييم العقاري الإلزامي للأجانب وتُحدَّد أجرته بتعرفة حدّ أدنى تصدر سنوياً وتتغير كل عام — اسأل شركة التقييم المرخَّصة عن التعرفة السارية قبل الدفع + رسوم النوتر والدوائر الرسمية حسب المعاملة.',
    last_update = '2026-07'
WHERE id = 'investor-property-buying-process';

UPDATE consultant_scenarios SET
    cost = 'الوساطة: أجرتها ليست رقماً ثابتاً — تُحدَّد بـ«تعرفة الحد الأدنى لأجور الوساطة» التي تُنشر سنوياً في الجريدة الرسمية وتتغير كل عام. وإذا كان نزاعك نزاع مستهلك (كشرائك شقة من شركة إنشاء) فإن أجرة الوساطة الخاصة بالمستهلك تُدفع في حالات محددة من ميزانية وزارة العدل (المادة 73/A من القانون 6502) — فلا تدفع شيئاً قبل أن تسأل الوسيط عن ذلك. المحكمة: الرسوم حسب قيمة النزاع.',
    last_update = '2026-07'
WHERE id = 'investor-property-dispute';

UPDATE consultant_scenarios SET
    tip = 'إذا كنت لا تقيم في تركيا وتؤجر عقارك فأنت مكلَّف "محدود" (dar mükellef): القانون لا يُلزمك بتعيين ممثل ضريبي، لكن المادة 107/4 من قانون ضريبة الدخل تجعل التبليغ الضريبي موجَّهاً إلى ممثلك الدائم إن وُجد، وإن لم يوجد فإلى من يدفع لك الإيراد (المستأجر). تعيين محاسب أو ممثل خيار عملي لتفادي فوات المواعيد، وليس التزاماً قانونياً. وعدم تقديم الإقرار في موعده يُعرّضك لغرامات.',
    last_update = '2026-07'
WHERE id = 'investor-tax-obligations';

UPDATE consultant_scenarios SET
    steps = '["حدد نوع الطلاق: اتفاقي (Anlaşmalı) أو نزاعي/شقاق (Çekişmeli). الاتفاقي أسرع لكنه يحتاج اتفاق مكتوب على الحقوق.", "اجمع أدلة أساسية: الزواج، السكن، الأطفال، الدخل، وأي مراسلات مهمة (عند النزاع).", "استشر محامياً لتقدير أثر الطلاق على الإقامة/الأطفال، خصوصاً إذا كان أحد الطرفين يعتمد على الإقامة العائلية. واعلم أن القانون يفتح لك باباً: إذا كنت أجنبياً متزوجاً من مواطن تركي وأمضيت 3 سنوات على الأقل بإقامة عائلية، يجوز منحك إقامة قصيرة الأمد بعد الطلاق؛ وإذا ثبت بقرار محكمة أنك ضحية عنف أسري يسقط شرط الثلاث سنوات (المادة 34/6 من القانون 6458). النص يقول «يجوز أن تُمنح» ولا يجعلها تلقائية، لكنه أساس قانوني تتقدّم به إلى إدارة الهجرة. واعلم أن القانون يفتح لك باباً: إذا كنت أجنبياً متزوجاً من مواطن تركي وأمضيت 3 سنوات على الأقل بإقامة عائلية، يجوز منحك إقامة قصيرة الأمد بعد الطلاق؛ وإذا ثبت بقرار محكمة أنك ضحية عنف أسري يسقط شرط الثلاث سنوات (المادة 34/6 من القانون 6458). النص يقول «يجوز أن تُمنح» ولا يجعلها تلقائية، لكنه أساس قانوني تتقدّم به إلى إدارة الهجرة.", "إذا كان اتفاقياً: جهّز بروتوكول اتفاق واضح (نفقة/حضانة/زيارة/تقسيم ممتلكات إن وجدت) ثم حدّد موعد المحكمة.", "بعد الحكم: تابع إجراءات تثبيت/ترجمة الحكم عند الحاجة (قنصلية/أبوستيل/ترجمة محلفة) حسب الدولة والجهة المطلوبة."]'::jsonb,
    last_update = '2026-07'
WHERE id = 'legal-divorce';

UPDATE consultant_scenarios SET
    cost = 'سكن الدولة (KYK/GSB): الأجرة الشهرية تختلف حسب نوع المهجع وتاريخ التسكين ويحددها كل عام مديرية القروض والمهاجع (KYGM)، وتظهر لك على شاشة الدفع بعد التسكين، ويُضاف إليها «مبلغ ضمان» يُعاد عند إلغاء القيد — راجع kygm.gsb.gov.tr قبل الاعتماد على أي رقم متداول. السكن الخاص أغلى بأضعاف وتختلف أسعاره كثيراً بين المدينة والحي.',
    last_update = '2026-07'
WHERE id = 'student-dormitory';

UPDATE consultant_scenarios SET
    cost = 'النسخة الأولى مجانية في جميع الجامعات (قرار YÖK)؛ النسخ الإضافية قد تخضع لرسم حسب لائحة الجامعة.',
    description = 'هي ملحق للدبلوم (Diploma Supplement) إصداره إلزامي على جميع مؤسسات التعليم العالي في تركيا منذ نهاية العام الدراسي 2005-2006 بقرار من مجلس التعليم العالي (YÖK)، ويُصدر بإحدى اللغات: الإنكليزية أو الألمانية أو الفرنسية. ليست “جنسية” ولا “تأشيرة”، لكنها تسهّل فهم شهادتك دولياً وقد تساعد في معادلات أو تقديمات خارجية.',
    steps = '["اسأل جامعتك إن كانت تصدر Diploma Supplement/الشهادة الزرقاء.", "النسخة الأولى مجانية بحسب YÖK، فلا تدفع رسماً مقابلها. اسأل شؤون الطلاب فقط عن آلية الطلب: بعض الجامعات (الحاصلة على Diploma Supplement Label) تصدرها تلقائياً مع التخرج، والباقي يصدرها بناءً على طلب الطالب.", "اطلبها بعد التخرج أو مع الدبلوم حسب نظام الجامعة.", "احتفظ بنسخة ورقية ورقمية، وقد تحتاج ترجمة في بعض الدول.", "لا تعتمد عليها وحدها؛ غالباً ستحتاج أيضاً كشف درجات ومحتوى مواد."]'::jsonb,
    last_update = '2026-07'
WHERE id = 'student-mavi-diploma';

UPDATE consultant_scenarios SET
    cost = 'رسم التسجيل الجديد 400 ليرة للعام الدراسي 2025-2026 (يُدفع عبر odeme.meb.gov.tr أو بنوك زراعات/وقف بنك/خلق بنك برقم الهوية أو رقم الأجنبي)، ويُدفع مجدداً عند تجديد القيد كل فصل، إضافة إلى الكتب. وهناك إعفاء كامل من الرسم لتسع فئات يوثّقها دليل MEB، منها من لديه تقرير لجنة طبية بنسبة إعاقة 40٪ فأكثر، وأسر الشهداء والمحاربين القدامى، والمشمولون بالقانونين 6284 و5395.',
    last_update = '2026-07'
WHERE id = 'student-open-highschool';

UPDATE consultant_scenarios SET
    cost = 'طلاب المدارس والجامعات التركية معفون من رسم الإقامة (Harç) بموجب المادة 88/أ من قانون الرسوم 492، ويدفعون فقط بدل بطاقة الإقامة 964 ل.ت (2026) + التأمين الصحي. المسجّلون في دورات اللغة (تومر) على إقامة قصيرة الأمد لا يشملهم هذا الإعفاء، لكن السوريين والفلسطينيين وعدداً من الجنسيات معفون من الـHarç بمبدأ المعاملة بالمثل • للتفاصيل الكاملة: /article/residence-permit-fees-2026',
    description = 'إقامة الطالب غالباً أقوى وأسهل من السياحية لأنها مبنية على قبول/تسجيل تعليمي، لكن انتبه: المادة 38/3 من القانون 6458 تنص صراحةً على أنها لا تمنح أي حق إقامة للأب أو الأم أو أي قريب. نجاح الملف يعتمد على: تسجيل فعلي + وثيقة طالب صحيحة + تأمين مناسب + عنوان ثابت + تقديم التمديد خلال آخر 60 يوماً وقبل انتهاء الإقامة في كل الأحوال (المادة 24/2).',
    last_update = '2026-07'
WHERE id = 'student-residence';

UPDATE consultant_scenarios SET
    description = 'ترشيح السوريين للجنسية الاستثنائية بفضل مؤهلاتهم (أصحاب تصاريح العمل الطويلة، شهادات جامعية، أساتذة، أطباء). تنبيه أساسي: بطاقة الحماية المؤقتة (الكملك) بحد ذاتها لا تمنح صاحبها حق التقدّم للجنسية التركية، ولا تُحتسب مدتها ضمن مدد الإقامة، ولا تمنح انتقالاً للإقامة الدائمة — المادة 25 من لائحة الحماية المؤقتة. أي شخص يعرض عليك «تقديم ملف جنسية» بالكملك وحده فهو يبيعك وهماً. تنبيه أساسي: بطاقة الحماية المؤقتة (الكملك) بحد ذاتها لا تمنح صاحبها حق التقدّم للجنسية التركية، ولا تُحتسب مدتها ضمن مدد الإقامة، ولا تمنح انتقالاً للإقامة الدائمة — المادة 25 من لائحة الحماية المؤقتة. أي شخص يعرض عليك «تقديم ملف جنسية» بالكملك وحده فهو يبيعك وهماً.',
    last_update = '2026-07'
WHERE id = 'syrian-citizenship';

UPDATE consultant_scenarios SET
    legal = 'قرارات وزارة الداخلية وإدارة الهجرة بشأن كثافة الأجانب في الأحياء: عتبة الـ 20٪ المطبّقة منذ 1 تموز/يوليو 2022 ما تزال سارية كأساس قانوني، لكن قرارات إعادة الفتح الصادرة في حزيران/يونيو 2026 شطبت معظم الأحياء من قائمة الإغلاق — نحو 80٪ من القائمة على مستوى تركيا؛ ففي إسطنبول لم يبقَ سوى 5 أحياء من أصل 54 وفق قائمة مديرية الهجرة بتاريخ 7 حزيران/يونيو 2026، وفي غازي عنتاب بقي 57 حياً من أصل 163 بعد قرار 9 حزيران/يونيو 2026. القوائم محلية وتتغيّر، والمرجع النهائي هو مديرية الهجرة في ولايتك.',
    tip = 'معظم الأحياء التي كانت مغلقة أُعيد فتحها في حزيران/يونيو 2026، لكن قائمة صغيرة ما تزال مغلقة وتختلف بين ولاية وأخرى — فالمطلوب أن تتحقّق، لا أن تفترض الإغلاق ولا أن تفترض الفتح. قبل دفع أي عربون: تأكّد من حالة الحي عبر أداة «فاحص المناطق» في الموقع أو بالاتصال على الرقم 157 (مجاني وبالعربية). إن تبيّن أن الحي ما يزال مغلقاً فلا تستأجر فيه مهما كانت المغريات، ولا تصدّق أي وسيط يعدك بتدبير تسجيل عنوان في حي مغلق مقابل مال — التثبيت هناك مرفوض نظامياً والنتيجة خسارة المال وعقد لا يمكن تثبيته في النفوس.',
    related_article_id = 'address-registration-closed',
    last_update = '2026-07'
WHERE id = 'syrian-prohibited-check';

UPDATE consultant_scenarios SET
    docs = '["جواز السفر الساري + صورة عن الإقامة الحالية", "تأمين صحي مُجدَّد يغطي الفترة الجديدة", "عقد إيجار ساري المفعول أو سند ملكية", "كشف حساب بنكي حديث", "صورتان (2) بيومتريتان مأخوذتان خلال آخر 6 أشهر، بخلفية بيضاء ومطابقتان لمعايير ICAO", "أضف إلى قائمة المستندات: «وثيقة عنوان UETS (نظام التبليغ الإلكتروني الوطني) تُستخرج من فروع PTT المركزية — إلزامية في طلبات التمديد» و«وثيقة مكان السكن (Yerleşim Yeri Belgesi) حديثة من e-Devlet»."]'::jsonb,
    steps = '["قدّم طلب التجديد عبر بوابة e-ikamet خلال آخر 60 يوماً من إقامتك الحالية: باب التقديم يُفتح عندما يتبقى 60 يوماً على انتهائها، ويجب في كل الأحوال تقديمه قبل تاريخ الانتهاء (المادة 24/2 من قانون 6458).", "جدّد التأمين الصحي ليغطي الفترة الجديدة كاملة.", "تأكد من أن عنوان النفوس محدّث ومطابق لعقد الإيجار الحالي.", "ادفع رسوم التجديد (Harç + Kart Bedeli) واحتفظ بالإيصال.", "اذهب في الموعد المحدد مع الملف الكامل لإتمام البيومتري.", "خلال فترة الانتظار: احصل على «وثيقة مراجعة طلب الإقامة» (İkamet İzni Müracaat Belgesi) — تُسلَّم مجاناً وبلا رسوم، وهي التي تمنحك حق البقاء قانونياً حتى صدور القرار حتى لو انتهت بطاقتك القديمة. احتفظ بها مطبوعة معك."]'::jsonb,
    last_update = '2026-07'
WHERE id = 'tourist-extension';

UPDATE consultant_scenarios SET
    docs = '["بطاقة الإقامة", "احذف «تقرير الدخل من SGK» — الأجانب لا يخضعون لفحص الدخل (gelir testi)، فهو خاص بفئة أخرى من المؤمَّنين. قسط التأمين الصحي العام للأجانب يُحسب بنسبة 12% من أساسٍ محدد بالقانون يساوي ضعف الحد الأدنى الإجمالي للأجور، بغضّ النظر عن دخلك (المادتان 80 و81/و من قانون 5510). المستندات المطلوبة عملياً: بطاقة الإقامة السارية، ورقم الأجنبي (Yabancı Kimlik No)، وطلب التسجيل مع التصريح بعدم وجود تغطية تأمينية من بلدك. استفسر عن قيمة القسط الحالية من مركز SGK مباشرة.", "رقم ضريبي"]'::jsonb,
    last_update = '2026-07'
WHERE id = 'tourist-health-insurance';

UPDATE consultant_scenarios SET
    steps = '["اطلب عقداً مكتوباً بالتركية (Kira Sözleşmesi) وترجمه إن لزم", "تأكد من وجود: اسم المالك، العنوان، المبلغ، مدة العقد، شروط التجديد", "لا توقّع على تعهد إخلاء (Tahliye Taahhüdü) مع العقد — وقّعه لاحقاً فقط إذا أردت", "لا تسلّم التأمين (Depozito) نقداً ولا تحوّله إلى حساب المالك. القانون يوجب إيداع المبلغ في حساب توفير لأجل باسمك لا يستطيع المالك السحب منه دون موافقتك؛ وإذا لم يُبلّغ المالك البنك خطياً خلال ثلاثة أشهر من انتهاء العقد بأنه أقام دعوى أو تنفيذاً ضدك، وجب على البنك إعادة المبلغ إليك بناءً على طلبك (المادة 342 من قانون الالتزامات 6098).", "سجّل عنوانك في النفوس خلال 20 يوم عمل من الانتقال (المادة 50/3 من قانون 5490)", "صوّر حالة الشقة عند الاستلام كدليل"]'::jsonb,
    last_update = '2026-07'
WHERE id = 'tourist-lease-contract';

UPDATE consultant_scenarios SET
    docs = '["جواز سفر ساري المفعول (صلاحية لا تقل عن 60 يوماً بعد مدة الإقامة المطلوبة)", "صورتان (2) بيومتريتان مأخوذتان خلال آخر 6 أشهر، خلفية بيضاء، مطابقتان لمعايير ICAO", "تأمين صحي يغطي كامل فترة الإقامة (شركة تأمين معتمدة من إدارة الهجرة)", "عقد إيجار مصدق من النوتير أو سند ملكية (Tapu)", "إثبات القدرة المالية: المعيار النظامي هو القدرة على تغطية مصروف شهري لا يقل عن صافي الحد الأدنى للأجور المعمول به في سنة التقديم (28,075.50 ل.ت شهرياً لعام 2026)، مع ثلث الحد الأدنى إضافةً عن كل فرد من أفراد الأسرة، ولا يُقبل الاستناد إلى تعهّد طرف ثالث وحده (المادة 22/6 من اللائحة التنفيذية).", "وصل دفع رسوم الإقامة (Harç + Kart Bedeli)"]'::jsonb,
    last_update = '2026-07'
WHERE id = 'tourist-new';

UPDATE consultant_scenarios SET
    steps = '["حدد مدة التجاوز: احسب عدد الأيام من تاريخ انتهاء الفيزا/الإقامة حتى اليوم.", "راجع إدارة الهجرة (İl Göç İdaresi) طوعياً — المراجعة الطوعية تخفف العقوبة مقارنة بالضبط في نقطة تفتيش.", "ادفع الغرامة المقررة: تُحسب يومياً وتتراكم (حوالي 100-150 ليرة/يوم حسب تحديث 2026).", "قد يصدر بحقك قرار منع دخول — ولكن القانون يجيز عدم إصداره إذا بادرتَ بنفسك قبل أن تُضبط ودفعتَ الرسوم والغرامات المستحقة، أو إذا غادرت خلال مهلة «الدعوة للمغادرة» (المادة 9/4 و9/5 من قانون 6458).", "غادر تركيا خلال المهلة المحددة في القرار: لا تقل عن 15 يوماً وتصل إلى 30 يوماً (المادة 56/1 من قانون 6458). ولا تُمنح هذه المهلة أصلاً لمن يوجد بحقه خطر هروب، أو خالف قواعد الدخول/الخروج القانوني، أو استخدم وثائق مزوّرة، أو شكّل تهديداً للنظام والأمن أو الصحة العامة. ومن مُنح مهلة يُسلَّم «وثيقة إذن خروج» (Çıkış İzin Belgesi) بلا أي رسم.", "إن صدر بحقك قرار ترحيل (Sınır Dışı Etme Kararı) فمهلة الطعن أمام المحكمة الإدارية 7 أيام فقط من تاريخ التبليغ، ولا يجوز ترحيلك خلال مهلة رفع الدعوى ولا حتى انتهاء المحاكمة (المادة 53/3 من قانون 6458). أما قرار منع الدخول وحده فمهلة الطعن فيه 60 يوماً (المادة 7 من قانون 2577)."]'::jsonb,
    last_update = '2026-07'
WHERE id = 'tourist-overstay';

UPDATE consultant_scenarios SET
    tip = 'الحدود الرسمية معلنة ولا تحتاج تخميناً: يجب التصريح لموظف الجمارك عند الدخول أو الخروج إذا كان معك أكثر من 25,000 ليرة تركية، أو ما يعادل 10,000 يورو بالعملات الأجنبية. التصريح يتم على «نموذج التصريح النقدي» (Nakit Beyan Formu) الذي تطلبه من موظف الجمارك. وإذا لم تصرّح واكتُشف المبلغ: غرامة إدارية بنسبة 10% من المبلغ غير المصرَّح عنه، ويُوضع كامل النقد الذي بحوزتك تحت الحجز. تحقق من الأرقام قبل السفر على موقع وزارة التجارة (ticaret.gov.tr). الحدود الرسمية معلنة ولا تحتاج تخميناً: إدخال النقد إلى تركيا حر من حيث المبدأ، أما عند الخروج من تركيا فيجب التصريح لموظف الجمارك إذا كان معك أكثر من 25,000 ليرة تركية أو ما يعادل 10,000 يورو بالعملات الأجنبية — على «نموذج التصريح النقدي» (Nakit Beyan Formu) الذي تطلبه من موظف الجمارك قبل ختم الجواز. إذا لم تصرّح واكتُشف المبلغ: غرامة إدارية بنسبة 10% من المبلغ غير المصرَّح عنه، ويُوضع كامل النقد الذي بحوزتك تحت الحفظ. أجب بصدق إذا سألك موظف الجمارك عن النقد في الاتجاهين، واحمل إثبات مصدر الأموال، وتحقق من الأرقام قبل السفر على موقع وزارة التجارة (ticaret.gov.tr).',
    last_update = '2026-07'
WHERE id = 'travel-cash-limit';

UPDATE consultant_scenarios SET
    steps = '["تواصل مع شركة الطيران أولاً لأن لديهم شروط وزن/صندوق/حجز للحيوانات. وانتبه لقيد رسمي أهم: بموجب التعليمات التركية لا يُسمح بإدخال أكثر من حيوانين (2) بصحبة المسافر الواحد (مثلاً قطتان، أو قطة وكلب)، ويجب أن تكون كل الوثائق (الشهادات والاختبارات) صادرة بشكل منفصل لكل حيوان. وبما أن الفحص البيطري عند الدخول لا يتوفر في كل منفذ، تأكد مسبقاً من وزارة الزراعة والغابات أو من شركة الطيران أن مطار/معبر وصولك يستقبل الحيوانات المصاحبة قبل حجز التذكرة. وانتبه لقيد رسمي أهم: لا يُسمح بإدخال أكثر من حيوانين (2) بصحبة المسافر الواحد (مثلاً قطتان، أو قطة وكلب)، ويجب أن تكون كل الأوراق مُصدَرة بشكل منفصل لكل حيوان. كما أن دخول القطط والكلاب والنمس إلى تركيا لا يتم إلا عبر البوابات الحدودية التي تحددها وزارة الزراعة والغابات — تأكد من أن مطار وصولك من ضمنها.", "جهّز الشريحة الإلكترونية (Microchip) إن كانت مطلوبة.", "أكمل لقاح داء الكلب ضمن المدد المطلوبة، واستخرج شهادة صحية بيطرية رسمية.", "للدخول إلى تركيا، اختبار عيار الأجسام المضادة للكَلَب ليس اختيارياً: يجب سحب عينة الدم بعد آخر لقاح كَلَب بـ 30 يوماً على الأقل، ولا يُسمح بدخول الحيوان إلى تركيا قبل مرور 3 أشهر على تاريخ سحب العينة. مثال رسمي: لقاح 01/04 ← أبكر سحب دم 01/05 ← أبكر تاريخ دخول 01/08. يُعفى من شرط الثلاثة أشهر الحيوانُ تركي المنشأ العائد ومعه تقرير عيار سابق صالح. تحقق أيضاً من شروط بلد وجهتك إن كنت مسافراً من تركيا.", "في يوم السفر: احضر مبكراً، واحتفظ بكل الأوراق أصل + نسخ."]'::jsonb,
    last_update = '2026-07'
WHERE id = 'travel-pets';

UPDATE consultant_scenarios SET
    description = 'هذا المسار مناسب لمن لديه نشاط تجاري حقيقي ويريد إذن عمل كمدير/مالك. التحدي الأساسي هو شروط الشركة (رأس مال 500,000 ليرة وحصة 20% على الأقل) وشرط توظيف خمسة مواطنين أتراك مقابل كل أجنبي — وهو القاعدة الأساسية وليس احتمالاً، ولا يُستثنى منه إلا حالات محدودة.',
    last_update = '2026-07'
WHERE id = 'work-permit-company';

UPDATE consultant_scenarios SET
    title = 'تكلفة إذن العمل 2026 (ما الذي يُدفع فعلاً)',
    last_update = '2026-07'
WHERE id = 'work-permit-cost';

UPDATE consultant_scenarios SET
    description = 'يحتاج الكملك للإذن للعمل القانوني. صاحب العمل (الشركة) هو من يقدم لك. شرط أساسي: لا يمكن تقديم الطلب إلا بعد مرور ستة أشهر على تاريخ تسجيلك في الحماية المؤقتة (المادة 5 من لائحة أذون عمل الحماية المؤقتة) — قبل ذلك يرفض النظام الطلب تلقائياً. شرط أساسي: لا يمكن تقديم الطلب إلا بعد مرور ستة أشهر على تاريخ تسجيلك في الحماية المؤقتة (المادة 5 من لائحة أذون عمل الحماية المؤقتة) — قبل ذلك يرفض النظام الطلب تلقائياً.',
    docs = '["الكملك (يُفضَّل أن يكون مسجلاً في ولاية العمل). ويمكن تقديم الطلب لولاية غير ولاية تسجيلك؛ فإذا قُبل الطلب تراجع مديرية الهجرة في الولاية لنقل قيد إقامتك إليها. أما إعفاء العمل الزراعي/الحيواني الموسمي فيشترط تقديمه في ولاية التسجيل نفسها.", "صورة شخصية", "عقد العمل المبرم مع الشركة"]'::jsonb,
    steps = '["صاحب العمل يستخدم المحاسب المالي (Mali Müşavir) لتقديم الطلب عبر بوابة وزارة العمل. تحقق أولاً من الحصة (kota): كقاعدة عامة لا يتجاوز عدد العاملين تحت الحماية المؤقتة في المنشأة 10% من عدد الموظفين الأتراك، وفي المنشآت التي يقل مجموع عامليها عن عشرة يُسمح بعامل واحد فقط (المادة 8 من لائحة أذون عمل الحماية المؤقتة). استثناء مهم: إذا حصل صاحب العمل على وثيقة من مديرية العمل (İŞKUR) تثبت عدم العثور خلال الأسابيع الأربعة السابقة للطلب على مواطن تركي بنفس مؤهلات الوظيفة، جاز عدم تطبيق الحصة (المادة 8/3). تحقق أولاً من الحصة (kota): كقاعدة عامة لا يتجاوز عدد العاملين تحت الحماية المؤقتة في المنشأة 10% من عدد الموظفين الأتراك، وفي المنشآت التي يقل مجموع عامليها عن عشرة يُسمح بعامل واحد فقط (المادة 8 من لائحة أذون عمل الحماية المؤقتة). استثناء مهم: إذا حصل صاحب العمل على وثيقة من مديرية العمل (İŞKUR) تثبت عدم العثور خلال الأسابيع الأربعة السابقة للطلب على مواطن تركي بنفس مؤهلات الوظيفة، جاز عدم تطبيق الحصة (المادة 8/3).", "الموافقة على الطلب عبر E-Devlet الخاص بك.", "دفع رسوم الإذن + بدل الورقة الثمينة من قِبل الشركة خلال 30 يوماً من تاريخ الإشعار وإلا يُرفض الطلب. وبعد الموافقة، على صاحب العمل تقديم إشعار بدء التأمين (sigortalı işe giriş bildirgesi) خلال 30 يوماً من تاريخ الموافقة أو التبليغ. تابع الأمرين بنفسك.", "انتظار بطاقة إذن العمل."]'::jsonb,
    tip = 'تأكد دورياً عبر E-Devlet ليس فقط من دفع التأمينات بل من المبلغ المُصرَّح به: لا يجوز دفع أجر أقل من الحد الأدنى لحاملي الحماية المؤقتة (المادة 10 من لائحة أذون عملهم)، ولا يجوز أن يكون أساس احتساب التأمينات أقل من الأجر المُصرَّح به في طلب إذن العمل.',
    last_update = '2026-07'
WHERE id = 'work-permit-employee';

UPDATE consultant_scenarios SET
    legal = 'لائحة الحماية المؤقتة (Geçici Koruma Yönetmeliği) المادة 27، المعدّلة بالقرار الرئاسي رقم 10658 المنشور في الجريدة الرسمية بتاريخ 28/11/2025 — وهي مصدر رسوم المشاركة الصحية. أما قانون الضمان 5510 ولوائح GSS فتخص المواطنين والفئات المشمولة بـ GSS.',
    last_update = '2026-07'
WHERE id = 'work-sgk';

UPDATE consultant_scenarios SET
    cost = 'اشتراك شهري يُحسب كنسبة 35.75% من الدخل المُصرَّح به، وبحد أدنى مرتبط بالحد الأدنى للأجر. في 2026: الحد الأدنى للاشتراك ≈ 11,808 ليرة شهرياً (35.75% × 33,030 ليرة). قد ينخفض قليلاً عند استحقاق خصم الخزينة بشرط عدم وجود ديون.',
    last_update = '2026-07'
WHERE id = 'worker-bagkur';

UPDATE consultant_scenarios SET
    steps = '["تحتاج إذن عمل ساري حتى للعمل الحر — والترتيب مهم: تُنجز أولاً تسجيل النشاط (سجل ضريبي + سجل تجاري أو سجل الغرفة)، ثم تقدّم أنت بنفسك طلب إذن العمل المستقل مرفقاً بهذه الوثائق، ويجب صدور الإذن قبل أن تبدأ العمل فعلياً. ولحاملي الحماية المؤقتة شرط إضافي: مرور ستة أشهر على تاريخ التسجيل. وإذن العمل المستقل لغير حاملي الحماية المؤقتة تقديري وليس حقاً.", "افتح سجلاً ضريبياً كشخص حقيقي (Şahıs Şirketi) في مكتب الضرائب", "سجّل في SGK كمستقل (4/b — Bağ-Kur)", "أصدر فواتير رسمية لكل عمل (e-Arşiv Fatura عبر e-Devlet)", "قدّم إقرار ضريبة الدخل ربع سنوي (Geçici Vergi) وسنوي"]'::jsonb,
    last_update = '2026-07'
WHERE id = 'worker-freelance-rules';

UPDATE consultant_scenarios SET
    cost = 'الوساطة: إذا لم يتم الاتفاق تدفع وزارة العدل أجر أول ساعتين من الجلسات (وما زاد عن الساعتين يُقسَّم بالتساوي بينكما ما لم تتفقا على غير ذلك). أما إذا انتهت الوساطة باتفاق فيُقسَّم أجر الوسيط بالتساوي بينك وبين صاحب العمل ما لم تتفقا على غير ذلك (المادة 3/13 من القانون 7036). وإذا تغيّبتَ عن الجلسة الأولى بلا عذر مقبول فستتحمل نصف مصاريف التقاضي التي على الطرف الآخر حتى لو كسبتَ الدعوى لاحقاً، ولن يُحكم لك إلا بنصف أتعاب المحاماة. المحكمة: رسوم قليلة مع إمكانية الإعفاء (adli yardım).',
    steps = '["وثّق كل شيء: عقد العمل، كشوف الرواتب، رسائل التواصل", "أرسل إنذاراً رسمياً عبر النوتر (İhtarname)", "قدّم طلب وساطة إلزامية (Arabuluculuk) — مجاني للعمال", "انتبه للمواعيد: في حالة الفصل غير القانوني يجب تقديم طلب الوساطة خلال شهر واحد من تاريخ تبليغك بإنهاء العقد (المادة 20 من قانون العمل 4857)، ثم رفع الدعوى في محكمة العمل خلال أسبوعين من تاريخ محضر الوساطة الأخير. تجاوز أي من الموعدين يُسقط حقك في العودة إلى العمل.", "يمكنك المطالبة بالراتب المتأخر دائماً. أما التعويضات فتختلف: تعويض الأقدمية (Kıdem) يشترط إتمام سنة كاملة على الأقل في العمل؛ وتعويض الإشعار (İhbar) يستحقه فقط من أُنهي عقده من الطرف الآخر دون احترام مهلة الإشعار — فإذا استقلت أنت لسبب مُحق (كعدم دفع الراتب) فلا تستحق تعويض الإشعار."]'::jsonb,
    last_update = '2026-07'
WHERE id = 'worker-rights-violation';

